#include <assert.h>
#include <stdio.h>
#include <math.h>
#include "../native/engine.h"
int main(int argc,char**argv){assert(argc==2);tsf*b=load_font(argv[1]);assert(b&&b->prBank&&b->presets[0].regionNum==6);assert(b->fontSamples[0]==1.0f/8388608);tsf_set_max_voices(b,288);tsf_channel_set_presetindex(b,0,0);PrChannelFx*p=part_new(48000);tsf_set_output(b,TSF_STEREO_INTERLEAVED,48000,-10);smart_note(b,60,100);assert(tsf_active_voice_count(b)==2);int first=0;for(int i=0;i<b->voiceNum;i++)if(b->voices[i].playingPreset>=0&&b->voices[i].region->offset==0)first++;assert(first==1);float pcm[512];tsf_render_float(b,pcm,256,0);for(int i=0;i<512;i++)assert(isfinite(pcm[i]));part_pedal(b,p,127);part_release(b,p,60);assert(b->prRelease[60]);int keyRelease=0;for(int i=0;i<b->voiceNum;i++)if(b->voices[i].playingPreset>=0&&b->voices[i].region->prTrigger==2)keyRelease++;assert(keyRelease==1);part_pedal(b,p,0);assert(!b->prRelease[60]);int release=0;for(int i=0;i<b->voiceNum;i++)if(b->voices[i].playingPreset>=0&&b->voices[i].region->prTrigger==1)release++;assert(release==1);smart_note(b,60,100);int second=0;for(int i=0;i<b->voiceNum;i++)if(b->voices[i].playingPreset>=0&&b->voices[i].region->offset==4096)second++;assert(second==1);silence(b);assert(!b->prRelease[60]&&tsf_active_voice_count(b)==0);free(p);tsf_close(b);puts("Packed bank: true PCM24 LSB, stereo regions, round robin, release-key and deferred pedal release passed");}
